import {entityIconPicker,entityIcon} from './entity-icons.js';
import {kanbanHTML,taskViewToggle} from './kanban.js';
import {recurrenceLabel,repeatForm} from './recurrence.js';
import {projectLabel,projectArea,projectTasks,areaTasks,taskArea,taskStatus,repeatLabels,isProjectArchived,isProjectAvailable} from './domain.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'short',timeZone:'UTC'}):'Без срока';
const statusNames={todo:'К выполнению',done:'Выполнена',cancelled:'Отменена',someday:'Когда-нибудь'};
export function statusBadge(t){return `<span class="task-status ${taskStatus(t)}">${statusNames[taskStatus(t)]}</span>`;}
export function areaOptions(state,selected){return '<option value="">Без зоны</option>'+state.areas.map(a=>`<option value="${esc(a.id)}" ${selected===a.id?'selected':''}>${esc(a.name)}</option>`).join('');}
export function projectOptions(state,selected,empty='Без проекта · самостоятельная'){return `<option value="">${empty}</option>`+state.projects.filter(p=>!p.parentId&&isProjectAvailable(state,p)).flatMap(p=>[p,...state.projects.filter(c=>c.parentId===p.id&&isProjectAvailable(state,c))]).map(p=>`<option value="${esc(p.id)}" ${selected===p.id?'selected':''}>${esc(projectLabel(state,p.id))}</option>`).join('');}
export function taskTable(state,tasks,context={}){
  if(!tasks.length)return `<div class="empty-state"><span class="empty-symbol">⊹</span>Пока нет задач<p>Добавьте первый шаг или измените фильтры.</p><button class="secondary-button" data-action="new-task" data-project="${esc(context.projectId||'')}" data-area="${esc(context.areaId||'')}">Добавить задачу</button></div>`;
  return `<div class="task-table-wrap"><table class="workspace-table"><thead><tr><th>Задача</th><th>Где находится</th><th>Срок</th><th>Статус</th><th></th></tr></thead><tbody>${tasks.map(t=>{const area=state.areas.find(a=>a.id===taskArea(state,t));return `<tr><td><div class="table-task"><button class="task-check ${t.done?'checked':''} ${t.cancelled?'cancelled-check':''}" data-action="toggle-done" data-id="${esc(t.id)}" aria-label="${esc((t.done?'Вернуть в работу: ':'Завершить: ')+t.title)}" aria-pressed="${t.done}" ${t.cancelled?'disabled':''}>${t.cancelled?'−':t.done?'✓':''}</button><div><button class="task-title ${t.done?'completed':''} ${t.cancelled?'cancelled-title':''}" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button>${t.recurrence!=='none'?`<span class="repeat-pill">↻ ${recurrenceLabel(t)}</span>`:''}</div></div></td><td><div class="relation-path">${area?`<button data-action="open-area" data-id="${esc(area.id)}">${esc(area.name)}</button>`:'<span>Без зоны</span>'}${t.projectId?`<button data-action="open-project" data-id="${esc(t.projectId)}">${esc(projectLabel(state,t.projectId))}</button>`:'<span class="standalone-label">Самостоятельная</span>'}</div></td><td class="table-date">${date(t.due)}</td><td>${statusBadge(t)}</td><td><div class="table-actions"><button class="entity-edit" data-action="edit-task" data-id="${esc(t.id)}" aria-label="Изменить ${esc(t.title)}">✎</button>${!t.done&&!t.cancelled?`<button class="entity-edit cancel-action" data-action="cancel-task" data-id="${esc(t.id)}" aria-label="Отменить ${esc(t.title)}">×</button>`:''}</div></td></tr>`;}).join('')}</tbody></table></div>`;
}
function progress(tasks){const active=tasks.filter(t=>!t.cancelled);return active.length?Math.round(active.filter(t=>t.done).length/active.length*100):0;}
function collectionViewToggle(layout){return `<div class="habit-view-toggle collection-view-toggle" role="group" aria-label="Вид раздела"><button data-action="collection-view" data-view="cards" aria-pressed="${layout!=='list'}" title="Карточки">▦ <span>Карточки</span></button><button data-action="collection-view" data-view="list" aria-pressed="${layout==='list'}" title="Список">☷ <span>Список</span></button></div>`;}
function projectCards(state,projects,layout='cards'){return projects.length?`<div class="entity-grid ${layout==='list'?'entity-list':''}">${projects.map(p=>{const tasks=projectTasks(state,p.id),children=state.projects.filter(c=>c.parentId===p.id),area=state.areas.find(a=>a.id===projectArea(state,p));return `<article class="entity-card"><div class="entity-card-top"><span class="entity-symbol">${entityIcon(p,'project')}</span><span class="entity-card-category">${area?esc(area.name):'Без зоны'}</span></div><h2><button data-action="open-project" data-id="${esc(p.id)}">${esc(p.name)}</button></h2><p class="entity-description">${esc(p.description||'У каждого проекта есть следующий шаг.')}</p><div class="entity-card-stats"><span>${tasks.filter(t=>t.done).length} / ${tasks.length} задач</span><span>${progress(tasks)}%</span></div><div class="entity-progress"><i style="width:${progress(tasks)}%"></i></div>${children.length?`<div class="subproject-list">${children.map(c=>`<button data-action="open-project" data-id="${esc(c.id)}"><span>↳ ${esc(c.name)}</span><span>${projectTasks(state,c.id).length} задач ›</span></button>`).join('')}</div>`:''}<div class="entity-card-footer"><button class="entity-edit" data-action="edit-project" data-id="${esc(p.id)}" aria-label="Изменить проект ${esc(p.name)}">✎</button><button class="text-button" data-action="open-project" data-id="${esc(p.id)}">Открыть проект ↗</button>${!p.parentId?`<button class="text-button" data-action="new-project" data-parent="${esc(p.id)}">+ Подпроект</button>`:''}</div></article>`;}).join('')}</div>`:'<div class="empty-state"><span class="empty-symbol">◇</span>Проекты появятся здесь<p>Соберите задачи вокруг конкретного результата.</p><button class="secondary-button" data-action="new-project">Создать проект</button></div>';}
export function collectionBody(state,ctx){
  const {view,entityId,search='',statusFilter='open',areaFilter='',projectFilter='',layout='cards',repeatFilter='all'}=ctx,q=search.toLocaleLowerCase();
  if(view==='tasks'){
    const tasks=state.tasks.filter(t=>(statusFilter==='archived'?t.archived:!t.archived)&&(statusFilter==='open'?taskStatus(t)==='todo':statusFilter==='done'?t.done:statusFilter==='cancelled'?t.cancelled:true)&&(repeatFilter==='all'||repeatFilter==='recurring'&&t.recurrence!=='none'||repeatFilter==='once'&&t.recurrence==='none')&&(!q||(t.title+' '+projectLabel(state,t.projectId)+' '+(state.areas.find(a=>a.id===taskArea(state,t))?.name||'')).toLocaleLowerCase().includes(q))&&(!areaFilter||(areaFilter==='none'?!taskArea(state,t):taskArea(state,t)===areaFilter))&&(!projectFilter||(projectFilter==='none'?!t.projectId:t.projectId===projectFilter||state.projects.find(p=>p.id===t.projectId)?.parentId===projectFilter)));
    if(layout==='kanban')return kanbanHTML(state,tasks);
    return `<div class="list-caption">Найдено задач: ${tasks.length}<span>Общие статусы для всех периодов</span></div><section class="panel workspace-list">${taskTable(state,tasks)}</section>`;
  }
  if(view==='projects'){
    const p=state.projects.find(p=>p.id===entityId);if(p){const children=state.projects.filter(c=>c.parentId===p.id),tasks=projectTasks(state,p.id),direct=tasks.filter(t=>t.projectId===p.id);return `${children.length?`<div class="section-title"><h2>Подпроекты <span class="count">${children.length}</span></h2><span>Второй уровень</span></div>${projectCards(state,children,layout)}`:''}<div class="section-title"><h2>Задачи проекта <span class="count">${direct.length}</span></h2><button class="text-button" data-action="new-task" data-project="${esc(p.id)}">+ Добавить задачу</button></div><section class="panel workspace-list">${taskTable(state,direct,{projectId:p.id})}</section>${children.length?`<div class="scope-note">Задачи подпроектов находятся внутри каждого подпроекта. Всего в проекте: ${tasks.length} задач.</div>`:''}`;}
    const roots=state.projects.filter(p=>!p.parentId&&(!q||p.name.toLocaleLowerCase().includes(q)||state.projects.some(c=>c.parentId===p.id&&c.name.toLocaleLowerCase().includes(q))));return projectCards(state,roots,layout);
  }
  const a=state.areas.find(a=>a.id===entityId);if(a){const projects=state.projects.filter(p=>!p.parentId&&p.areaId===a.id),standalone=areaTasks(state,a.id).filter(t=>!t.projectId);return `<div class="section-title"><h2>Проекты <span class="count">${projects.length}</span></h2><button class="text-button" data-action="new-project" data-area="${esc(a.id)}">+ Новый проект</button></div>${projects.length?projectCards(state,projects,layout):'<div class="quiet-empty">В этой зоне пока нет проектов.</div>'}<div class="section-title"><h2>Самостоятельные задачи <span class="count">${standalone.length}</span></h2><button class="text-button" data-action="new-task" data-area="${esc(a.id)}">+ Добавить задачу</button></div><section class="panel workspace-list">${taskTable(state,standalone,{areaId:a.id})}</section>`;}
  const areas=state.areas.filter(a=>!q||(a.name+' '+a.description).toLocaleLowerCase().includes(q));return areas.length?`<div class="entity-grid ${layout==='list'?'entity-list':''}">${areas.map(a=>{const tasks=areaTasks(state,a.id),roots=state.projects.filter(p=>!p.parentId&&p.areaId===a.id);return `<article class="entity-card area-card"><div class="entity-card-top"><span class="entity-symbol">◎</span><h2 class="area-card-name"><button data-action="open-area" data-id="${esc(a.id)}">${esc(a.name)}</button></h2></div><div class="area-card-counts"><span><b>${roots.length}</b> проектов</span><span><b>${tasks.filter(t=>!t.projectId).length}</b> самостоятельных задач</span></div><div class="entity-card-footer"><button class="entity-edit" data-action="edit-area" data-id="${esc(a.id)}" aria-label="Изменить зону ${esc(a.name)}">✎</button><button class="text-button" data-action="open-area" data-id="${esc(a.id)}">Открыть зону ↗</button><span>${tasks.filter(t=>!t.done&&!t.cancelled).length} открытых задач</span></div></article>`;}).join('')}</div>`:'<div class="panel empty-state"><span class="empty-symbol">◎</span>Что требует постоянного внимания?<p>Создайте зоны, например «Работа», «Здоровье» или «Дом».<br>Внутри можно держать проекты и самостоятельные задачи.</p><button class="primary-button" data-action="new-area">Создать зону</button></div>';
}
export function collectionHTML(state,ctx){
  const p=ctx.view==='projects'&&state.projects.find(p=>p.id===ctx.entityId),a=ctx.view==='areas'&&state.areas.find(a=>a.id===ctx.entityId),entity=p||a;
  const title=entity?.name||({projects:'Проекты',areas:'Зоны ответственности',tasks:'Задачи'})[ctx.view];
  let description=entity?.description||({projects:'Результаты, к которым движемся. От большого проекта — к следующему шагу.',areas:'Постоянные сферы жизни: проекты и самостоятельные задачи в одном месте.',tasks:'Один список действий. Связи, повторения и история выполнения.'})[ctx.view];
  let crumbs=`<button data-action="page" data-page="${ctx.view}">${({projects:'Все проекты',areas:'Все зоны',tasks:'Все задачи'})[ctx.view]}</button>`;
  if(p){const area=state.areas.find(a=>a.id===projectArea(state,p)),parent=state.projects.find(x=>x.id===p.parentId);if(area)crumbs+=`<span>›</span><button data-action="open-area" data-id="${esc(area.id)}">${esc(area.name)}</button>`;if(parent)crumbs+=`<span>›</span><button data-action="open-project" data-id="${esc(parent.id)}">${esc(parent.name)}</button>`;}
  if(entity)crumbs+=`<span>›</span><span>${esc(entity.name)}</span>`;
  return `${entity?`<div class="collection-breadcrumbs">${crumbs}</div>`:''}<div class="collection-heading"><div>${entity?`<div class="eyebrow">${p?(p.parentId?'ПОДПРОЕКТ · УРОВЕНЬ 2':'ПРОЕКТ · УРОВЕНЬ 1'):'ПОСТОЯННАЯ СФЕРА'}</div>`:''}<h1>${esc(title)}</h1><p class="subtitle">${esc(description)}</p></div><div class="collection-heading-actions">${ctx.view!=='tasks'?collectionViewToggle(ctx.layout):taskViewToggle(ctx.layout)}${entity?`<button class="secondary-button" data-action="edit-${p?'project':'area'}" data-id="${esc(entity.id)}">Изменить</button>`:''}${p?`${!p.parentId?`<button class="secondary-button" data-action="new-project" data-parent="${esc(p.id)}">+ Подпроект</button>`:''}<button class="primary-button" data-action="new-task" data-project="${esc(p.id)}">+ Задача</button>`:a?`<button class="primary-button" data-action="new-project" data-area="${esc(a.id)}">+ Проект</button>`:`<button class="primary-button" data-action="${ctx.view==='projects'?'new-project':ctx.view==='areas'?'new-area':'new-task'}">+ ${ctx.view==='projects'?'Новый проект':ctx.view==='areas'?'Новая зона':'Новая задача'}</button>`}</div></div>${!entity?`<div class="collection-tools"><label class="search-wrap"><input id="collection-search" type="search" value="${esc(ctx.search)}" placeholder="${ctx.view==='tasks'?'Найти задачу, проект или зону':'Найти по названию'}" aria-label="Поиск на странице"></label>${ctx.view==='tasks'?`<select class="field" id="collection-status" aria-label="Статус задач">${[['open','Открытые'],['all','Все активные'],['done','Выполненные'],['cancelled','Отменённые'],['archived','Архив']].map(([v,l])=>`<option value="${v}" ${ctx.statusFilter===v?'selected':''}>${l}</option>`).join('')}</select><select class="field" id="collection-repeat" aria-label="Повторения задач"><option value="all">Любые повторения</option><option value="recurring" ${ctx.repeatFilter==='recurring'?'selected':''}>Повторяющиеся</option><option value="once" ${ctx.repeatFilter==='once'?'selected':''}>Однократные</option></select><select class="field" id="collection-area" aria-label="Зона задач"><option value="">Все зоны</option><option value="none">Без зоны</option>${state.areas.map(a=>`<option value="${esc(a.id)}" ${ctx.areaFilter===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><select class="field" id="collection-project" aria-label="Проект задач">${projectOptions(state,ctx.projectFilter,'Все проекты').replace('<option value="">Все проекты</option>','<option value="">Все проекты</option><option value="none">Самостоятельные</option>')}</select>`:''}</div>`:''}<div id="collection-results">${collectionBody(state,ctx)}</div><div class="collection-footer">${ctx.view==='projects'?'Проект → подпроект. Два уровня, общая зона ответственности.':ctx.view==='areas'?'Зона объединяет проекты и задачи, которым не нужен отдельный проект.':'Повторения создаются после выполнения. Отмена сохраняет историю планов.'}</div>`;
}
export function entityForm(state,kind,entity={},defaults={}){
  const isProject=kind==='project',hasChildren=isProject&&state.projects.some(p=>p.parentId===entity.id),parentId=entity.parentId||defaults.parentId||'',areaId=entity.areaId||defaults.areaId||'';
  return `<h2>${isProject?(entity.id?'Изменить проект':'Новый проект'):(entity.id?'Изменить зону':'Новая зона ответственности')}</h2><p class="modal-description">${isProject?'Два уровня: проект и подпроект. Подпроект наследует зону родителя.':'Зона объединяет проекты и самостоятельные задачи.'}</p><form id="entity-form" data-kind="${kind}" data-id="${esc(entity.id||'')}"><label class="form-label" for="entity-name">Название</label><input id="entity-name" class="field" required maxlength="100" value="${esc(entity.name||'')}">${entityIconPicker(entity,kind)}<label class="form-label" for="entity-description">Описание</label><textarea id="entity-description" class="field" rows="3" maxlength="3000" placeholder="Какой результат или сфера внимания?">${esc(entity.description||'')}</textarea>${isProject?`<label class="form-label" for="entity-parent">Родительский проект</label><select id="entity-parent" class="field" ${hasChildren?'disabled':''}><option value="">Нет · основной проект</option>${state.projects.filter(p=>!p.parentId&&p.id!==entity.id&&isProjectAvailable(state,p)).map(p=>`<option value="${esc(p.id)}" ${p.id===parentId?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${hasChildren?'<p class="form-note">У проекта есть подпроекты. Их нужно перенести, прежде чем сделать этот проект подпроектом.</p>':''}<label class="form-label" for="entity-area">Зона ответственности</label><select id="entity-area" class="field" ${parentId?'disabled':''}>${areaOptions(state,parentId?state.projects.find(p=>p.id===parentId)?.areaId:areaId)}</select><p class="form-note">Изменение зоны основного проекта перенесёт также его подпроекты и задачи.</p>`:''}<div class="error-text" id="entity-error" role="alert"></div>${isProject&&entity.id?`<div class="entity-lifecycle-actions">${!entity.completedAt?`<button type="button" class="secondary-button" data-action="complete-project" data-id="${esc(entity.id)}">Завершить проект</button>`:''}<button type="button" class="secondary-button" data-action="archive-project" data-id="${esc(entity.id)}">Архивировать проект</button><button type="button" class="danger-button" data-action="delete-project" data-id="${esc(entity.id)}">Удалить проект</button></div>`:''}<div class="modal-actions"><button type="button" class="secondary-button" data-action="close-modal">Отмена</button><button class="primary-button" type="submit">Сохранить ${isProject?'проект':'зону'}</button></div></form>`;
}
export function taskForm(state,t,isNew){return `<h2>${isNew?'Новая задача':'Живая задача'}</h2><p class="modal-description">Задача может относиться к проекту или напрямую к зоне. Изменения не переписывают исходные планы.</p><form id="task-form"><label class="form-label" for="edit-title">Название</label><textarea id="edit-title" class="field" rows="2" maxlength="1000" required>${esc(t.title)}</textarea><div class="form-grid"><div><label class="form-label" for="edit-project-id">Проект</label><select class="field" id="edit-project-id">${projectOptions(state,t.projectId)}</select></div><div><label class="form-label" for="edit-area-id">Зона ответственности</label><select class="field" id="edit-area-id" ${t.projectId?'disabled':''}>${areaOptions(state,t.projectId?taskArea(state,t):t.areaId)}</select></div><div><label class="form-label" for="edit-estimate">Оценка, часов</label><input class="field" id="edit-estimate" type="number" min="0" max="8760" step="0.5" value="${t.estimate}" required></div><div><label class="form-label" for="edit-due">Срок</label><input class="field" id="edit-due" type="date" value="${esc(t.due)}"></div><div><label class="form-label" for="edit-status">Статус</label><select class="field" id="edit-status">${Object.entries(statusNames).map(([v,l])=>`<option value="${v}" ${taskStatus(t)===v?'selected':''}>${l}</option>`).join('')}</select></div></div>${repeatForm(t)}<div id="completed-date-wrap" ${!t.done?'hidden':''}><label class="form-label" for="edit-completed">Дата выполнения</label><input class="field" id="edit-completed" type="date" value="${esc(t.completedAt||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Aqtobe'}).format(new Date()))}"></div><label class="form-label" for="edit-source">Файл в Obsidian</label><input class="field" id="edit-source" value="${esc(t.source)}" maxlength="250" required ${isNew?'':'readonly'}>${t.nextOccurrenceId?'<div class="form-note">Следующий экземпляр уже создан. Повторное завершение этой записи не создаст дубликат. Изменение или отмена касается только этого экземпляра.</div>':''}${!isNew?`<div class="form-note">ID блока: <b>^${esc(t.blockId)}</b>${t.archived?' · в архиве':''}${state.vault?' · <a class="text-button" href="'+esc('obsidian://open?'+new URLSearchParams({vault:state.vault,file:t.source.replace(/\.md$/i,'')+'#^'+t.blockId}))+'">Открыть в Obsidian ↗</a>':''}</div>`:''}<div class="error-text" id="form-error" role="alert"></div><div class="modal-actions">${!isNew?`<button type="button" class="danger-button" data-action="${t.archived?'undo-archive':'archive-task'}" data-id="${esc(t.id)}">${t.archived?'Вернуть из архива':'Убрать в архив'}</button>`:''}<button type="button" class="secondary-button" data-action="close-modal">Отмена</button><button class="primary-button" type="submit">Сохранить задачу</button></div></form>`;}
